input.newString:
function setStatus(id: number, status: 'fulfilled' | 'deleted'): ListingRow | undefined {
  const db = getDb();
  const listing = getListingById(id);
  if (!listing) {
    return undefined;
  }

  const transitionMatrix = {
    active: ['fulfilled', 'deleted'],
    fulfilled: ['deleted'],
  } as const;

  const allowedTransitions = transitionMatrix[listing.status];
  if (!allowedTransitions?.includes(status)) {
    throw new Error(
      `Cannot transition listing #${id} from '${listing.status}' to '${status}'.`,
    );
  }

  db.update(listings).set({ status, updatedAt: now() }).where(eq(listings.id, id)).run();
  return getListingById(id);
}

