input.oldString:
describe('status transition guards', () => {
  function seedServerAndListings(): {
    activeListing: { id: number; status: string };
    fulfilledListing: { id: number; status: string };
  } {
    seedServer();
    const active = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    const fulfilled = createListing({ ...baseInput(), intent: 'want', accepts: 'cash' });
    fulfillListing(fulfilled.listing.id);
    return {
      activeListing: { id: active.listing.id, status: active.listing.status },
      fulfilledListing: { id: fulfilled.listing.id, status: fulfilled.listing.status },
    };
  }

  describe('legal transitions', () => {
    it('active to fulfilled succeeds', () => {
      seedServer();
      const listing = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
      expect(listing.status).toBe('active');

      const updated = fulfillListing(listing.listing.id);
      expect(updated?.status).toBe('fulfilled');
    });

    it('active to deleted succeeds', () => {
      seedServer();
      const listing = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
      expect(listing.status).toBe('active');

      const updated = softDeleteListing(listing.listing.id);
      expect(updated?.status).toBe('deleted');
    });

    it('fulfilled to deleted succeeds', () => {
      seedServer();
      const listing = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
      fulfillListing(listing.listing.id);

      const updated = softDeleteListing(listing.listing.id);
      expect(updated?.status).toBe('deleted');
    });
  });

  describe('forbidden transitions', () => {
    it('re-fulfilling an already-fulfilled listing throws', () => {
      seedServerAndListings();
      const { fulfilledListing } = seedServerAndListings();
      expect(() => fulfillListing(fulfilledListing.id)).toThrow(
        /cannot transition from 'fulfilled' to 'fulfilled'/i,
      );
    });

    it('re-deleting an already-deleted listing throws', () => {
      const { } = seedServerAndListings();
      const { fulfilledListing } = seedServerAndListings();
      fulfillListing(fulfilledListing.id);
      softDeleteListing(fulfilledListing.id);

      expect(() => softDeleteListing(fulfilledListing.id)).toThrow(
        /cannot transition from 'deleted' to 'deleted'/i,
      );
    });

    it('fulfilling a deleted listing throws', () => {
      seedServer();
      const listing = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
      softDeleteListing(listing.listing.id);

      expect(() => fulfillListing(listing.listing.id)).toThrow(
        /cannot transition from 'deleted' to 'fulfilled'/i,
      );
    });

    it('fulfilling an expired listing throws', () => {
      seedServer();
      const listing = createListing({
        ...baseInput(),
        intent: 'have',
        accepts: 'cash',
      });
      // Manually expire the listing
      getDb().update(listings).set({ expiresAt: Date.now() - 1 }).where(eq(listings.id, listing.listing.id)).run();

      expect(() => fulfillListing(listing.listing.id)).toThrow(
        /cannot transition from 'active' to 'fulfilled' on an expired/i,
      );
    });

    it('deleted an expired listing throws', () => {
      seedServer();
      const listing = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
      // Manually expire the listing
      getDb().update(listings).set({ expiresAt: Date.now() - 1 }).where(eq(listings.id, listing.listing.id)).run();

      expect(() => softDeleteListing(listing.listing.id)).toThrow(
        /cannot transition from 'active' to 'deleted' on an expired/i,
      );
    });

    it('forbidden transitions leave the listing status unchanged', () => {
      const { } = seedServerAndListings();
      const { fulfilledListing } = seedServerAndListings();
      const db = getDb();

      // First transition: fulfilled -> deleted should succeed
      db.update(listings).set({ expiresAt: Date.now() - 1 }).where(eq(listings.id, fulfilledListing.id)).run();

      const beforeDeleted = db.select().from(listings).where(eq(listings.id, fulfilledListing.id)).get();
      expect(beforeDeleted?.status).toBe('fulfilled');

      // Try to fulfill the deleted/expired listing - should fail
      expect(() => fulfillListing(fulfilledListing.id)).toThrow();

      // Status must still be 'fulfilled' (unchanged)
      const afterFailed = db.select().from(listings).where(eq(listings.id, fulfilledListing.id)).get();
      expect(afterFailed?.status).toBe('fulfilled');
    });
  });
});

