describe('status transition guards', () => {
  it.each<[string, number, string]>([
    ['active', fulfillListing, 'fulfilled'],
    ['active', softDeleteListing, 'deleted'],
    ['fulfilled', softDeleteListing, 'deleted'],
  ])(
    'legal transition: %s to %s succeeds and updates status',
    (_fromStatus, setStatus, toStatus) => {
      seedServer();
      const listing = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
      const setStatusFn = setStatus as (id: number) => ListingRow | undefined;

      const updated = setStatusFn(listing.listing.id);
      expect(updated?.status).toBe(toStatus);
    },
  );

  it('forbidden transition: re-fulfilling already-fulfilled throws', () => {
    seedServer();
    const listing = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    fulfillListing(listing.listing.id);

    expect(() => fulfillListing(listing.listing.id)).toThrow(/cannot transition from 'fulfilled' to 'fulfilled'/);
  });

  it('forbidden transition: re-deleting already-deleted throws', () => {
    seedServer();
    const listing = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    fulfillListing(listing.listing.id);
    softDeleteListing(listing.listing.id);

    expect(() => softDeleteListing(listing.listing.id)).toThrow(/cannot transition from 'deleted' to 'deleted'/);
  });

  it('forbidden transition: fulfilling a deleted listing throws', () => {
    seedServer();
    const listing = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    softDeleteListing(listing.listing.id);

    expect(() => fulfillListing(listing.listing.id)).toThrow(/cannot transition from 'deleted' to 'fulfilled'/);
  });

  it('forbidden transition: fulfilling an expired listing throws', () => {
    seedServer();
    const listing = createListing({
      ...baseInput(),
      intent: 'have',
      accepts: 'cash',
    });
    const db = getDb();
    const now = Date.now();
    db.update(listings).set({ expiresAt: now - 1 }).where(eq(listings.id, listing.listing.id)).run();

    expect(() => fulfillListing(listing.listing.id)).toThrow(/cannot transition/);
  });

  it('forbidden transition: deleting an expired listing throws', () => {
    seedServer();
    const listing = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    const db = getDb();
    const now = Date.now();
    db.update(listings).set({ expiresAt: now - 1 }).where(eq(listings.id, listing.listing.id)).run();

    expect(() => softDeleteListing(listing.listing.id)).toThrow(/cannot transition/);
  });

  it('forbidden transition leaves listing status unchanged', () => {
    seedServer();
    let listingId = 0;
    let currentStatus: string | undefined;

    async function getListingForTest() {
      const fresh = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
      const db = getDb();
      const now = Date.now();
      db.update(listings).set({ expiresAt: now - 1 }).where(eq(listings.id, fresh.listing.id)).run();
      listingId = fresh.listing.id;
      const updated = fresh;
      expect(updated?.status).toBe('active');
      return updated;
    }

    getListingForTest().then(async (listing) => {
      const db = getDb();
      // Attempt forbidden transition - should throw
      expect(() => fulfillListing(listing.id)).toThrow();

      // Verify status unchanged
      const after = db.select().from(listings).where(eq(listings.id, listing.id)).get();
      expect(after?.status).toBe('active');
    });
  });
});

