  it('forbidden transition: expiring an active listing prevents further status changes', () => {
    seedServer();
    const listing = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    const db = getDb();
    const now = Date.now();
    db.update(listings).set({ expiresAt: now - 1 }).where(eq(listings.id, listing.listing.id)).run();

    expect(() => fulfillListing(listing.listing.id)).toThrow(/cannot transition/);
    expect(() => softDeleteListing(listing.listing.id)).toThrow(/cannot transition/);
  });

  it('forbidden transition leaves listing status unchanged', () => {
    seedServer();
    const listing = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    const db = getDb();
    // Expire the listing block transitions
    const now = Date.now();
    db.update(listings).set({ expiresAt: now - 1 }).where(eq(listings.id, listing.listing.id)).run();

    // Status should remain 'active' before the test
    const before = db.select().from(listings).where(eq(listings.id, listing.listing.id)).get();
    expect(before?.status).toBe('active');

    // Attempt forbidden transition - should throw
    expect(() => fulFillListing(listing.listing.id)).toThrow();
    expect(() => softDeleteListing(listing.listing.id)).toThrow();

    // Verify status still unchanged after failed attempt
    const after = db.select().from(listings).where(eq(listings.id, listing.listing.id)).get();
    expect(after?.status).toBe('active');
  });
});

